"""MTN Ghana Foundation sponsorship proposal PDF (1 page, A4, ReportLab)."""
from pathlib import Path

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import (
    HRFlowable, Image, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle,
)

# ━━ Color Palette (auto-generated by pdf.py palette.generate) ━━
# Intent: authority | Mode: minimal | Harmony: split_complementary
# Contrast: text:bg=14.1 | accent:bg=3.9
ACCENT = colors.HexColor('#278a27')
TEXT_PRIMARY = colors.HexColor('#202223')
TEXT_MUTED = colors.HexColor('#767e83')
BG_SURFACE = colors.HexColor('#dde1e4')
BG_PAGE = colors.HexColor('#eff1f2')

TABLE_HEADER_COLOR = ACCENT
TABLE_HEADER_TEXT = colors.white
TABLE_ROW_EVEN = colors.white
TABLE_ROW_ODD = BG_SURFACE

BRAND_NAVY = colors.HexColor('#0b1526')  # TOVO LABs logo ink (brand asset)

OUT = Path(__file__).parent / "MTN_GrowWithMe_Sponsorship_Proposal.pdf"
MARK = Path(__file__).parent / "assets" / "tovo-labs-mark.png"

PAGE_W, PAGE_H = A4
M = 14 * mm
AVAIL = PAGE_W - 2 * M

doc = SimpleDocTemplate(
    str(OUT), pagesize=A4, leftMargin=M, rightMargin=M, topMargin=11 * mm, bottomMargin=10 * mm,
    title="GrowWithMe - Sponsorship Proposal - MTN Ghana Foundation",
    author="TOVO LABs", subject="Maternal & child health pilot sponsorship", creator="TOVO LABs",
)

s_title = ParagraphStyle("t", fontName="Helvetica-Bold", fontSize=17.5, leading=21, textColor=TEXT_PRIMARY)
s_sub = ParagraphStyle("s", fontName="Helvetica", fontSize=9.5, leading=13, textColor=TEXT_MUTED)
s_h = ParagraphStyle("h", fontName="Helvetica-Bold", fontSize=10.5, leading=13, textColor=ACCENT, spaceBefore=7, spaceAfter=2.5)
s_body = ParagraphStyle("b", fontName="Helvetica", fontSize=9, leading=12.2, textColor=TEXT_PRIMARY)
s_bullet = ParagraphStyle("bl", parent=s_body, leftIndent=10, bulletIndent=2, spaceAfter=1.4)
s_call = ParagraphStyle("c", fontName="Helvetica-Bold", fontSize=11, leading=14.5, textColor=colors.white)
s_calls = ParagraphStyle("cs", fontName="Helvetica", fontSize=9, leading=12, textColor=colors.HexColor('#e9f5e9'))
s_th = ParagraphStyle("th", fontName="Helvetica-Bold", fontSize=8.6, leading=10.5, textColor=TABLE_HEADER_TEXT)
s_td = ParagraphStyle("td", fontName="Helvetica", fontSize=8.6, leading=10.8, textColor=TEXT_PRIMARY)
s_tdb = ParagraphStyle("tdb", parent=s_td, fontName="Helvetica-Bold")
s_foot = ParagraphStyle("f", fontName="Helvetica", fontSize=8.6, leading=11.5, textColor=TEXT_PRIMARY)
s_brand = ParagraphStyle("br", fontName="Helvetica-Bold", fontSize=15, leading=16, textColor=BRAND_NAVY)
s_hdate = ParagraphStyle("hd", fontName="Helvetica", fontSize=8.5, leading=11, textColor=TEXT_MUTED, alignment=2)

story = []

# Header: TOVO mark + wordmark left, date right
mark = Image(str(MARK), width=15 * mm, height=15 * mm)
brand_p = Paragraph(
    'tovo <font color="#278a27">labs</font> &nbsp;&nbsp;<font size="8.6" color="#767e83">— Ghanaian software engineering &amp; product studio</font>', s_brand
)
head = Table([[mark, brand_p, Paragraph("Sponsorship Proposal<br/>October 2026", s_hdate)]],
             colWidths=[17 * mm, AVAIL - 17 * mm - 30 * mm, 30 * mm])
head.setStyle(TableStyle([
    ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
    ("LEFTRIGHTBORDER", (0, 0), (-1, -1), 0),
    ("TOPBOTTOMBORDER", (0, 0), (-1, -1), 0),
]))
story.append(head)
story.append(Spacer(1, 4))
story.append(HRFlowable(width="100%", thickness=0.7, color=ACCENT))
story.append(Spacer(1, 6))

story.append(Paragraph("GrowWithMe — offline maternal &amp; child health care for Northern Ghana", s_title))
story.append(Spacer(1, 2))
story.append(Paragraph("Sponsorship request to the MTN Ghana Foundation &nbsp;·&nbsp; Submitted by TOVO LABs (Abdul Hafis Mohammed, CEO)", s_sub))
story.append(Spacer(1, 5))

story.append(Paragraph("The initiative", s_h))
story.append(Paragraph(
    "GrowWithMe is a mobile health platform built by TOVO LABs for mothers and children under five in Northern Ghana, "
    "where distance, poor connectivity and low literacy keep families from timely care. The app works fully offline on a basic "
    "Android phone, and every life-critical message it sends — urgent referral alerts, care reminders — travels on MTN's network as SMS. "
    "The platform is built and working today; this sponsorship funds a 12-month supervised district pilot.", s_body))

story.append(Paragraph("What is already working (no pilot subsidy required to demo)", s_h))
for b in [
    "Offline IMCI-aligned triage (child + pregnancy) — works with zero network; deterministic clinical rules own every risk verdict",
    "WHO growth monitoring with automatic malnutrition flags (below −2 SD)",
    "Care calendar synced to Ghana's EPI immunization schedule, ANC/PNC visits, Vitamin A — with spoken reminders for low-literacy mothers",
    "\u201cNana\u201d, a voice-first AI health educator with an offline fallback for no-connectivity homes",
    "One-tap urgent alerts: PDF patient report SMSed to the nearest CHPS compound, volunteer responders and the referral hospital — every referral tracked to closure",
    "Facility dashboard surfacing missed visits, growth faltering and lost-to-follow-up families, each with an SMS nudge",
]:
    story.append(Paragraph(b, s_bullet, bulletText="•"))
story.append(Spacer(1, 4))

ask = Table([[Paragraph("Amount requested: GHS 150,000 &nbsp;—&nbsp; 12-month supervised district pilot<br/>"
                        "<font size=9>One district · ~40 community health workers (CHWs) · ~5 CHPS/facility sites · 1,500–2,000 mother–child registrations</font>", s_call)]],
            colWidths=[AVAIL])
ask.setStyle(TableStyle([
    ("BACKGROUND", (0, 0), (-1, -1), ACCENT),
    ("LEFTPADDING", (0, 0), (-1, -1), 9), ("RIGHTPADDING", (0, 0), (-1, -1), 9),
    ("TOPPADDING", (0, 0), (-1, -1), 6), ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
]))
story.append(ask)
story.append(Spacer(1, 6))

story.append(Paragraph("Use of funds", s_h))
rows = [
    [Paragraph("Item", s_th), Paragraph("What it covers", s_th), Paragraph("GHS", s_th)],
    [Paragraph("SMS &amp; alerts", s_td), Paragraph("Referral alerts and care reminders for ~1,500–2,000 families for 12 months", s_td), Paragraph("18,000", s_td)],
    [Paragraph("Devices", s_td), Paragraph("40 Android phones for community health workers", s_td), Paragraph("40,000", s_td)],
    [Paragraph("Data bundles", s_td), Paragraph("Monthly MTN data for CHWs and facility staff (12 months)", s_td), Paragraph("24,000", s_td)],
    [Paragraph("Training &amp; supervision", s_td), Paragraph("CHW onboarding, refresher training, field supervision and transport", s_td), Paragraph("48,000", s_td)],
    [Paragraph("Evaluation &amp; reporting", s_td), Paragraph("Pilot KPI tracking, data quality, final impact report to the Foundation", s_td), Paragraph("20,000", s_td)],
    [Paragraph("Total", s_tdb), Paragraph("", s_td), Paragraph("150,000", s_tdb)],
]
budget = Table(rows, colWidths=[0.20 * AVAIL, 0.64 * AVAIL, 0.16 * AVAIL], hAlign="CENTER")
budget.setStyle(TableStyle([
    ("BACKGROUND", (0, 0), (-1, 0), TABLE_HEADER_COLOR),
    ("ROWBACKGROUNDS", (0, 1), (-1, -2), [TABLE_ROW_EVEN, TABLE_ROW_ODD]),
    ("BACKGROUND", (0, -1), (-1, -1), BG_SURFACE),
    ("GRID", (0, 0), (-1, -1), 0.4, colors.white),
    ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
    ("LEFTPADDING", (0, 0), (-1, -1), 5), ("RIGHTPADDING", (0, 0), (-1, -1), 5),
    ("TOPPADDING", (0, 0), (-1, -1), 2.6), ("BOTTOMPADDING", (0, 0), (-1, -1), 2.6),
    ("ALIGN", (2, 0), (2, -1), "RIGHT"),
]))
story.append(budget)
story.append(Spacer(1, 2))

story.append(Paragraph("Why MTN — and what the Foundation gets", s_h))
story.append(Paragraph(
    "MTN's network already carries the life-critical leg of every GrowWithMe referral: SMS. Beyond funding, we would welcome "
    "zero-rating of the app's traffic so no mother pays data to be heard. In return, the Foundation is positioned as the connectivity "
    "partner powering closed-loop maternal and child referrals in Northern Ghana: named recognition in the pilot report and communications, "
    "a site visit to the pilot district, and a demo of the working product for the Foundation team at any time.", s_body))

story.append(Paragraph("Expected impact — pilot targets", s_h))
for b in [
    "1,500–2,000 mothers and children under five registered and actively followed in one district",
    "Every urgent alert time-stamped from danger sign to facility arrival — the referral loop measured, and closed, for the first time",
    "Measurable lift in EPI immunization-schedule completion and ANC/PNC attendance against the district baseline, via SMS nudges",
    "Growth faltering caught early (WHO −2 SD flags) with catch-up visits scheduled automatically",
]:
    story.append(Paragraph(b, s_bullet, bulletText="•"))

story.append(Spacer(1, 6))
story.append(HRFlowable(width="100%", thickness=0.5, color=BG_SURFACE))
story.append(Spacer(1, 4))
story.append(Paragraph(
    "<b>Abdul Hafis Mohammed</b> — CEO &amp; Software Engineer, TOVO LABs &nbsp;·&nbsp; 059 988 0977 &nbsp;·&nbsp; abdulhafis2847@gmail.com<br/>"
    "A 2¾-minute detailed demo video and a working Android APK are available on request.", s_foot))

doc.build(story)
print("PDF written:", OUT)
